// -------------------------------------------------------------------------------------------
// the declaration

/// [definition] **A refinement as declared** (module header): the receiving ring `R`, the words
/// `K`, each word's full ticks `w`, the stations `m` and the termination class, with the receiver's
/// grain `L_R` read from the ring's declared receiver.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Refinement {
    ring: usize,
    words: usize,
    span: usize,
    stations: usize,
    termination: usize,
    grain: u64,
    period: u64,
}

impl Refinement {
    /// **Declare a refinement** on a field: refused unless the ring has a declared receiver (its
    /// receiving map `R` and grain), `K, w, m ≥ 1`, the stations lie within one turn of the
    /// receiving ring (`m ≤ d_R`) and the termination class is a class of the exterior chart.
    pub fn declare(
        field: &Field,
        ring: usize,
        words: usize,
        span: usize,
        stations: usize,
        termination: usize,
    ) -> Result<Self, HnnError> {
        let receiver = field
            .receivers()
            .iter()
            .find(|receiver| receiver.ring == ring)
            .ok_or(HnnError::MissingReceivingMap { ring })?;
        if words == 0 || span == 0 || stations == 0 {
            return Err(HnnError::NonpositiveDeclaration);
        }
        let period = field.ring(ring).period();
        if stations as u64 > period {
            return Err(HnnError::Shape {
                what: "the section's stations within one turn of the receiving ring",
                expected: period as usize,
                found: stations,
            });
        }
        if termination >= field.alphabet() {
            return Err(HnnError::CellOutside {
                code: termination,
                alphabet: field.alphabet(),
            });
        }
        if !receiver.tolerance.is_positive() {
            return Err(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            });
        }
        let grain = receiver
            .tolerance
            .recip()
            .ceil()
            .to_integer()
            .to_u64()
            .ok_or(HnnError::Tolerance {
                tolerance: receiver.tolerance.clone(),
            })?;
        Ok(Self {
            ring,
            words,
            span,
            stations,
            termination,
            grain,
            period,
        })
    }

    /// `R`.
    pub fn ring(&self) -> usize {
        self.ring
    }

    /// `K`.
    pub fn words(&self) -> usize {
        self.words
    }

    /// `w`.
    pub fn span(&self) -> usize {
        self.span
    }

    /// `m`.
    pub fn stations(&self) -> usize {
        self.stations
    }

    /// The termination class.
    pub fn termination(&self) -> usize {
        self.termination
    }

    /// `L_R`.
    pub fn grain(&self) -> u64 {
        self.grain
    }

    /// **The junction step the section is read at**, `K·w` on the refinement's clock (the last
    /// word's last junction).
    pub fn last_epoch(&self) -> usize {
        self.words * self.span
    }

    /// **The refinement's reach** (the certified step's reading; `hnn::constitution::Reach`): its
    /// `m` stations read the receiving ring's anchor after `K·w` full ticks, and the request's moment
    /// enters at the open of every word, `n·w` for `n < K`; `phases` the most phases one moment
    /// occupied.
    pub fn reach(&self, phases: u64) -> Reach {
        Reach {
            receiver: self.ring,
            stations: vec![self.last_epoch() as u64; self.stations],
            entries: (0..self.words).map(|n| (n * self.span) as u64).collect(),
            phases,
        }
    }

    /// **The refinement's causal diamond** (Lean `HNN/Retention.diamond_recursion`): the field's
    /// source rings reach, the receiving ring observes, over `K·w` rounds.
    pub fn diamond(&self, field: &Field) -> Diamond {
        Diamond::over(field, self.ring, self.last_epoch())
    }

    /// **Station `j`'s phase on the response clock**, `(1 + j)/d_R` turns: the tick `τ + 1 + j` of
    /// the receiving ring's clock unwound from the request's last tick, read in the section's frame
    /// (module header). Its whole part is the station's winding.
    pub fn station_turns(&self, station: usize) -> Rat {
        Rat::new(
            BigInt::from(station as u64 + 1),
            BigInt::from(self.period),
        )
    }

    /// **The passage with its section placed** (module header, "The section continues the
    /// request's passage"): the request's moment continued by the locked data `cells[j]` (an
    /// unlocked station `None`) at their stations' residues on the receiving ring, one population
    /// ([`SourceMoment::continued`]).
    pub fn passage(
        &self,
        field: &Field,
        current: &Current,
        moment: &SourceMoment,
        cells: &[Option<usize>],
    ) -> Result<SourceMoment, HnnError> {
        if cells.len() != self.stations {
            return Err(HnnError::Shape {
                what: "one cell slot per station",
                expected: self.stations,
                found: cells.len(),
            });
        }
        moment.continued(field, current, self.ring, cells)
    }

    /// **The target phases of the section** (`hnn::ratio::TargetPhases`): each station's phase on
    /// the response clock, the section's frame carrying no stream winding (branch zero).
    pub fn target_phases(&self) -> TargetPhases {
        TargetPhases {
            branch: BigInt::zero(),
            phases: (0..self.stations).map(|j| self.station_turns(j)).collect(),
        }
    }
}

// -------------------------------------------------------------------------------------------
// the balance

/// [definition] **The refinement's balance** (module header, the first check): the field's power
/// plus the resonators' energy at the first word's open (`open`) and at the last junction (`end`),
/// every tick's stated terms summed over the `K` words, the jump at each later word's open
/// (`injected`, the request's moment re-entering, the only jump), the executed residual (every
/// tick's field residual with its loaded split, the resonators' chart and split, and the last
/// junction's) with its certified bound, whether every tick's own balance closes, whether the ticks
/// chain (each tick opens at the power and resonator energy the one before left, and a word's open
/// changes no resonator energy), and the commit when one follows.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RefinementBalance {
    pub words: usize,
    pub ticks: usize,
    pub open: Rat,
    pub end: Rat,
    pub injected: Rat,
    pub dissipation: Rat,
    pub resist: Rat,
    pub contrast: Rat,
    pub pump: Rat,
    pub resonator_dissipation: Rat,
    pub interconnection: Rat,
    pub residual: Rat,
    pub bound: Rat,
    pub every_tick_closes: bool,
    pub chained: bool,
    pub commit: Option<CommitWork>,
    /// The end change's power and resonator energy under the cut's forms, read at the commit: the
    /// commit's identity reads it against `end`.
    pub committed_from: Option<Rat>,
}

impl RefinementBalance {
    /// **The balance of a refinement's words**, the last ended at its last junction.
    fn of(words: &[Word<'_>]) -> Result<Self, HnnError> {
        let mut balance = Self {
            words: words.len(),
            ticks: 0,
            open: Rat::zero(),
            end: Rat::zero(),
            injected: Rat::zero(),
            dissipation: Rat::zero(),
            resist: Rat::zero(),
            contrast: Rat::zero(),
            pump: Rat::zero(),
            resonator_dissipation: Rat::zero(),
            interconnection: Rat::zero(),
            residual: Rat::zero(),
            bound: Rat::zero(),
            every_tick_closes: true,
            chained: true,
            commit: None,
            committed_from: None,
        };
        let mut previous: Option<(Rat, Rat)> = None;
        for (n, word) in words.iter().enumerate() {
            let fields = word.field_balances();
            let (first, last) = match (fields.first(), fields.last()) {
                (Some(first), Some(last)) => (first, last),
                _ => {
                    return Err(HnnError::Shape {
                        what: "a refinement word with at least one full tick",
                        expected: 1,
                        found: 0,
                    });
                }
            };
            match &previous {
                None => balance.open = &first.before + &first.resonator_before,
                Some((power, resonance)) => {
                    balance.injected += &first.before - power;
                    balance.chained &= first.resonator_before == *resonance;
                }
            }
            for (t, tick) in fields.iter().enumerate() {
                balance.ticks += 1;
                balance.every_tick_closes &= tick.closes();
                if let Some(next) = fields.get(t + 1) {
                    balance.chained &= tick.after == next.before
                        && tick.resonator_after == next.resonator_before;
                }
                balance.dissipation += &tick.dissipation;
                balance.resist += &tick.resist;
                balance.contrast += &tick.contrast;
                balance.pump += &tick.pump;
                balance.resonator_dissipation += &tick.resonator_dissipation;
                balance.interconnection += &tick.interconnection;
                balance.residual +=
                    tick.residual() + &tick.resonator_chart + &tick.resonator_split;
                balance.bound += &tick.bound + &tick.resonator_bound;
            }
            previous = Some((last.after.clone(), last.resonator_after.clone()));
            if n + 1 == words.len() {
                let released = word.released()?;
                balance.residual += &released.last;
                balance.bound += &released.last_bound;
                balance.end = &released.power + &last.resonator_after;
            }
        }
        Ok(balance)
    }

    /// The stated terms' sum: what the refinement's identity adds to its open.
    fn terms(&self) -> Rat {
        -&self.dissipation + &self.resist + &self.contrast + &self.residual + &self.pump
            - &self.resonator_dissipation
            + &self.interconnection
            + &self.injected
    }

    /// **It closes**: `end = open − dissipation + resist + Π_c + residual + pump − resonator
    /// dissipation + interconnection + injected`, the executed residual within its bound, every tick
    /// closing, the ticks chaining; and, when a commit follows, the end change's power under the
    /// committed forms is the end plus the deposition work `½⟨x, ΔΘ x⟩` (Lean
    /// `HNN/Word.field_commit_deposition`).
    pub fn closes(&self) -> bool {
        let identity = self.end == &self.open + self.terms();
        let committed = match (&self.commit, &self.committed_from) {
            (Some(commit), Some(from)) => {
                *from == self.end && commit.committed == &self.end + &commit.deposition
            }
            (None, None) => true,
            _ => false,
        };
        identity
            && self.residual.abs() <= self.bound
            && self.every_tick_closes
            && self.chained
            && committed
    }

    /// **The committed energy bound of the refinement** (`hnn::constitution`'s header, "The
    /// committed energy bound, enforced at the commit"; Lean `Holon/Deposition.{committed_energy_bound,
    /// active_element_growth}`), read after its commit: with the per-tick amplitude growth `g = 1 + ω`
    /// of the constitution it ran at and the commit's certified storage growth `ε_k`, the committed
    /// energy is at most
    ///
    /// ```text
    /// (1 + ε_k) · (Σ_(n<K) g^(K·w − n·w) · √P_inj + g^(K·w) · √((K·w + 1) · r))²
    /// ```
    ///
    /// `P_inj` the injection's power (the balance's open: the change opens at rest), each word
    /// re-injecting it; `r` the executed residual's certified bound. Each passive tick keeps the
    /// power and a contrast port's tick multiplies it by at most `g²` (`active_element_growth`), so
    /// `√P(t+1) ≤ g√P(t) + √|r_t|`, an injection adds `√P_inj` to `√P` (the triangle inequality in
    /// the power's norm), and `Σ_t √|r_t| ≤ √((K·w + 1) Σ_t |r_t|)`; the commit's deposition work
    /// is at most `ε_k` times the storage part (`certify_deposit`). The square roots are read at
    /// their dyadic ceilings on the word's transient lattice. Refused before a commit.
    pub fn energy_bound(
        &self,
        declared: &Refinement,
        amplitude: &Rat,
        storage_growth: &Rat,
        lattice: Option<&WordLattice>,
    ) -> Result<EnergyBound, HnnError> {
        let commit = self.commit.as_ref().ok_or(HnnError::Shape {
            what: "a refinement's balance carried across its commit",
            expected: 1,
            found: 0,
        })?;
        let grain = lattice.map_or(0, WordLattice::transient_exponent);
        let ticks = declared.last_epoch() as u64;
        let entries: Rat = (0..declared.words)
            .map(|n| power(amplitude, ticks - (n * declared.span) as u64))
            .sum();
        let residual = sqrt_ceiling(
            &(Rat::from_integer(BigInt::from(ticks + 1)) * self.bound.abs()),
            grain,
        );
        let root = entries * sqrt_ceiling(&self.open, grain) + power(amplitude, ticks) * residual;
        let bound = (Rat::one() + storage_growth) * &root * &root;
        Ok(EnergyBound {
            holds: commit.committed <= bound,
            committed: commit.committed.clone(),
            bound,
        })
    }

    /// **Carry the balance across the commit** from the cut's form `before` to the committed form
    /// `after` (both read at the refinement's lift): the deposition work on the end change and the
    /// end change's power and resonator energy under the committed forms.
    pub fn commit(
        &mut self,
        before: &PowerForm,
        after: &PowerForm,
        change: &EndChange,
    ) -> Result<(), HnnError> {
        let deposition = before.deposition_work(after, change)?;
        let from = before.power(change)? + before.resonator_power(change)?;
        let committed = after.power(change)? + after.resonator_power(change)?;
        self.committed_from = Some(from);
        self.commit = Some(CommitWork {
            deposition,
            committed,
        });
        Ok(())
    }
}

/// [definition] **A refinement's committed energy against its bound**
/// ([`RefinementBalance::energy_bound`]): the committed energy, the certified bound and whether it
/// holds.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EnergyBound {
    pub committed: Rat,
    pub bound: Rat,
    pub holds: bool,
}

// -------------------------------------------------------------------------------------------
// the section

/// [definition] **A refined section** (module header): the refinement's words (owned until the
/// return consumes them), the injection, the receiving map read at the cut, the anchor, each
/// station's read and the stations' faces, the end change and the balance.
#[derive(Debug)]
pub struct Section<'c> {
    field: &'c Field,
    declared: Refinement,
    words: Vec<Word<'c>>,
    injection: Vec<Vec<Rat>>,
    map: ExactRatMatrix,
    anchor: Vec<Rat>,
    reads: Vec<Vec<Rat>>,
    faces: Faces,
    end: EndChange,
    balance: RefinementBalance,
}

impl<'c> Section<'c> {
    /// **Refine a section** (module header): the operands read once at the cut (every word of the
    /// refinement reads the same medium), the change opened at rest with the passage's moment (the
    /// request's, continued by any placed section, [`Refinement::passage`]) injected at the source
    /// rings, `K` words of `w` full ticks with the motion continuing, the last ending at its last
    /// junction, and every station read from its anchor.
    pub fn refine(
        field: &'c Field,
        constitution: &impl ConstitutionRead,
        current: &Current,
        passage: &SourceMoment,
        declared: &Refinement,
        charts: &mut Charts,
    ) -> Result<Self, HnnError> {
        let operands = Operands::at_cut_charted(field, constitution, current, charts)?;
        let injection = passage.open_storage(field, constitution, current)?;
        Self::refine_on(field, constitution, operands, injection, declared)
    }

    /// **Refine on given operands**: the executed charts with no transient split for the pairing
    /// check ([`Pairing`]), or the cut's own.
    fn refine_on(
        field: &'c Field,
        constitution: &impl ConstitutionRead,
        operands: Operands,
        injection: Vec<Vec<Rat>>,
        declared: &Refinement,
    ) -> Result<Self, HnnError> {
        let map = constitution
            .receiving_map(declared.ring)
            .ok_or(HnnError::MissingReceivingMap {
                ring: declared.ring,
            })?
            .clone();
        let mut change = EndChange::rest(field, &operands);
        let mut words: Vec<Word<'c>> = Vec::with_capacity(declared.words);
        for n in 0..declared.words {
            let mut word = Word::continuing(
                field,
                operands.clone(),
                &change,
                &injection,
                n * declared.span,
            )?;
            word.run(declared.span)?;
            if n + 1 == declared.words {
                word.last_junction()?;
            } else {
                change = word.change()?;
            }
            words.push(word);
        }
        let last = words.last().expect("a refinement declares at least one word");
        let anchor = last
            .anchor(declared.span, declared.ring)
            .ok_or(HnnError::WordEnded {
                ticks: last.ticks(),
            })?
            .to_vec();
        let end = last.released()?.end;
        let ring = field.ring(declared.ring);
        let reads: Vec<Vec<Rat>> = (0..declared.stations)
            .map(|j| ring.rotate(&anchor, &BigInt::from(j as u64 + 1)))
            .collect();
        let logits = reads
            .iter()
            .map(|read| apply_rows(&map, read))
            .collect::<Result<Vec<_>, HnnError>>()?;
        let received: Vec<ReceivingRead> = logits
            .into_iter()
            .map(|logits| ReceivingRead::of_logits(logits, declared.grain))
            .collect();
        let faces = Faces::of_reads(&received, declared.grain)?;
        let balance = RefinementBalance::of(&words)?;
        Ok(Self {
            field,
            declared: declared.clone(),
            words,
            injection,
            map,
            anchor,
            reads,
            faces,
            end,
            balance,
        })
    }

    /// The declaration.
    pub fn declared(&self) -> &Refinement {
        &self.declared
    }

    /// The stations' faces, one per station, with their exact logits.
    pub fn faces(&self) -> &Faces {
        &self.faces
    }

    /// Each station's read `P_R^(1+j) v_R`.
    pub fn reads(&self) -> &[Vec<Rat>] {
        &self.reads
    }

    /// The receiving ring's anchor at the last junction: the section's one producing variable.
    pub fn anchor(&self) -> &[Rat] {
        &self.anchor
    }

    /// The refinement's balance.
    pub fn balance(&self) -> &RefinementBalance {
        &self.balance
    }

    /// The change the last word ended with, which the commit's deposition work reads.
    pub fn end(&self) -> &EndChange {
        &self.end
    }

    /// The largest exact bits of a wave, contact or resonator coordinate over the refinement's
    /// words, a reading.
    pub fn peak_bits(&self) -> u64 {
        self.words.iter().map(Word::peak_bits).max().unwrap_or(0)
    }

    /// Every word's carried remainders, released at its end, joined.
    pub fn released(&self) -> Result<Remainders, HnnError> {
        let mut joined = Remainders::default();
        for word in &self.words {
            joined = joined.join(&word.released()?.remainders);
        }
        Ok(joined)
    }

    /// **The release of the section** (module header): each station's top class at the grain,
    /// read over the grain fibre of its logits; width zero exactly when every station's top cell is
    /// unique, the discrete metric's one otherwise, attained at the first plural station; decided
    /// at tolerance zero by the holding rule through `receiver::release`.
    pub fn release(&self) -> Result<SectionRelease, HnnError> {
        let mut classes = Vec::with_capacity(self.faces.faces.len());
        let mut plural = Vec::new();
        for (j, face) in self.faces.faces.iter().enumerate() {
            let cells = face.cells();
            let mut top = 0;
            for (class, cell) in cells.iter().enumerate() {
                let (best, candidate) = (&cells[top], cell);
                if (&candidate.carry, candidate.phase) > (&best.carry, best.phase) {
                    top = class;
                }
            }
            let shared = cells
                .iter()
                .enumerate()
                .any(|(class, cell)| {
                    class != top
                        && cell.carry == cells[top].carry
                        && cell.phase == cells[top].phase
                });
            if shared {
                plural.push(j);
            }
            classes.push(top);
        }
        section_release(&self.declared, classes, plural)
    }

    /// **The section's Holon ratio against its targets**, one class per station, each target read
    /// at its station's phase on the response clock ([`Refinement::target_phases`]).
    pub fn compare(&self, targets: &[usize]) -> Result<HolonRatio, HnnError> {
        if targets.len() != self.declared.stations {
            return Err(HnnError::Shape {
                what: "one target per station",
                expected: self.declared.stations,
                found: targets.len(),
            });
        }
        HolonRatio::compare(self.faces.clone(), targets, &self.declared.target_phases())
    }

    /// **The section's Holon ratio at its compared stations only** (the unlocked ones; module
    /// header): each compared station's ratio as [`Section::compare`] reads it, a zero covector at
    /// the others.
    pub fn compare_partition(
        &self,
        targets: &[usize],
        compared: &[bool],
    ) -> Result<HolonRatio, HnnError> {
        if targets.len() != self.declared.stations {
            return Err(HnnError::Shape {
                what: "one target per station",
                expected: self.declared.stations,
                found: targets.len(),
            });
        }
        HolonRatio::compare_partition(
            self.faces.clone(),
            targets,
            &self.declared.target_phases(),
            compared,
        )
    }

    /// **The section's return** (module header, "Learning"): the covector at every station pulled
    /// back through `R` and the station's phase binding onto the anchor, then through the words in
    /// reverse, each by its own continuing return; the returns joined on the refinement's clock
    /// ([`join`]). It consumes the section: its words live only until here.
    pub fn pull_back(self, covector: &RatioCovector) -> Result<SectionReturn, HnnError> {
        let declared = self.declared.clone();
        let stations = covector.logits();
        if stations.len() != declared.stations {
            return Err(HnnError::Shape {
                what: "the covector's stations",
                expected: declared.stations,
                found: stations.len(),
            });
        }
        let ring = self.field.ring(declared.ring);
        let map_t = self.map.transpose()?;
        let mut anchor_covector = vec![Rat::zero(); ring.width()];
        for (j, gradient) in stations.iter().enumerate() {
            let pulled = apply_rows(&map_t, gradient)?;
            anchor_covector = add(
                &anchor_covector,
                &ring.rotate(&pulled, &-BigInt::from(j as u64 + 1)),
            );
        }
        let produced: Rat = stations
            .iter()
            .zip(&self.reads)
            .map(|(gradient, read)| -> Result<Rat, HnnError> {
                Ok(dot(gradient, &apply_rows(&self.map, read)?))
            })
            .sum::<Result<Rat, HnnError>>()?;
        let reads: Vec<(Vec<Rat>, Vec<Rat>)> = self
            .reads
            .iter()
            .cloned()
            .zip(stations.iter().cloned())
            .collect();
        let mut end: Option<ChangeCovector> = None;
        let mut returns: Vec<(WordReturn, ChangeCovector)> = Vec::with_capacity(declared.words);
        let count = self.words.len();
        for (n, word) in self.words.into_iter().enumerate().rev() {
            let mut anchors = vec![None; word.recorded().len()];
            if n + 1 == count {
                anchors[declared.span] = Some(anchor_covector.clone());
            }
            let (back, opening) =
                word.pull_back_continuing(anchors, declared.ring, end.as_ref())?;
            end = Some(opening.clone());
            returns.push((back, opening));
        }
        returns.reverse();
        let mut returned = Rat::zero();
        for (_, opening) in &returns {
            for (covector, injected) in opening.storage.iter().zip(&self.injection) {
                returned += dot(covector, injected);
            }
        }
        let joined = join(&returns, declared.span, reads)?;
        Ok(SectionReturn {
            joined,
            openings: returns.into_iter().map(|(_, opening)| opening).collect(),
            pairing: Pairing { produced, returned },
        })
    }
}

/// [definition] **A section's release** ([`Section::release`]): the decision, the width over the
/// section's fibre, each station's top class, the plural stations, the emitted classes (the
/// released section up to its first termination; empty unless released) and the first station at
/// the termination class.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SectionRelease {
    pub decision: ReleaseReturn,
    pub width: Rat,
    pub classes: Vec<usize>,
    pub plural: Vec<usize>,
    pub emitted: Vec<usize>,
    pub terminated: Option<usize>,
}

impl SectionRelease {
    /// Whether the section was released at width zero.
    pub fn released(&self) -> bool {
        matches!(self.decision, ReleaseReturn::Released { .. })
    }
}

/// **A section's release from its stations' classes and its plural stations** ([`Section::release`],
/// [`generate`]): width zero exactly when no station is plural, the discrete metric's one otherwise,
/// attained at the first plural station, decided at tolerance zero by the holding rule through
/// `receiver::release`; the released classes read up to the first termination.
fn section_release(
    declared: &Refinement,
    classes: Vec<usize>,
    plural: Vec<usize>,
) -> Result<SectionRelease, HnnError> {
    let (diameter, attaining) = match plural.first() {
        Some(&station) => (
            Rat::one(),
            WidthWitness::Coordinate {
                coordinate: station,
            },
        ),
        None => (Rat::zero(), WidthWitness::Point),
    };
    let width = ReceiverWidth::declared(
        format!("the section on receiving ring {}", declared.ring),
        "every station's top class at the grain, over the grain fibre of its logits",
        DiameterNorm::Supremum,
        diameter,
        attaining,
        classes.len().max(1),
    )?;
    let options = LawfulOptions::assemble(&width, Rat::zero(), None, false)?;
    let rule = DecisionRule::new(
        "the section's joint commit at tolerance zero",
        WithinTolerance::Release,
        BeyondTolerance::Hold,
    );
    let decision = release(&rule, &options)?;
    let terminated = classes
        .iter()
        .position(|&class| class == declared.termination);
    let emitted = match &decision {
        ReleaseReturn::Released { .. } => classes[..terminated.unwrap_or(classes.len())].to_vec(),
        _ => Vec::new(),
    };
    Ok(SectionRelease {
        decision,
        width: width.diameter().clone(),
        classes,
        plural,
        emitted,
        terminated,
    })
}

/// **A station's lock reading** at the grain `L`: its top class (the greatest grain cell, the
/// least class on a tie) and the gap in grain steps `(n_top − n_2) L + (k_top − k_2)` to the
/// runner-up cell, zero exactly when the top cell is shared (a plural reading).
fn lock_reading(face: &crate::hnn::ratio::Face, grain: u64) -> (usize, BigInt) {
    let cells = face.cells();
    let step = |cell: &crate::receiver::face::GrainCell| -> BigInt {
        &cell.carry * BigInt::from(grain) + BigInt::from(cell.phase)
    };
    let mut top = 0;
    for (class, cell) in cells.iter().enumerate() {
        if step(cell) > step(&cells[top]) {
            top = class;
        }
    }
    let runner = cells
        .iter()
        .enumerate()
        .filter(|&(class, _)| class != top)
        .map(|(_, cell)| step(cell))
        .max();
    let gap = match runner {
        Some(runner) => step(&cells[top]) - runner,
        None => BigInt::zero(),
    };
    (top, gap)
}

/// [definition; agent-inferred, U6's order repair] **The partition a training refinement compares**
/// (module header): the corruption chart of absorbing (masked) diffusion read on the stations. The
/// number `v` of locked stations is drawn uniformly from `0 … m − 1`, then `v` stations uniformly
/// (a partial Fisher–Yates draw); the rest are compared. Every partition a generation passes through
/// (nothing locked, then more) is one this law draws with positive mass, and at least one station is
/// always compared. `true` marks a locked (placed, uncompared) station.
pub fn mask(draw: &mut Draw, stations: usize) -> Vec<bool> {
    let mut order: Vec<usize> = (0..stations).collect();
    let locked = draw.below(stations.max(1));
    for i in 0..locked {
        let j = i + draw.below(stations - i);
        order.swap(i, j);
    }
    let mut visible = vec![false; stations];
    for &station in &order[..locked] {
        visible[station] = true;
    }
    visible
}

/// [definition] **The adjoint pairing of a section's return** (module header, the second check):
/// `produced = Σ_j ⟨g_j, R P_R^(1+j) v_R⟩`, the stations' covectors paired with their logits, and
/// `returned = Σ_n ⟨μ_n, injection⟩`, the returned opening covectors paired with what each word's
/// open added (the change opens at rest, so nothing else). On the executed charts with no transient split the two are equal
/// exactly; on the word's lattice they differ by the released remainders' work.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Pairing {
    pub produced: Rat,
    pub returned: Rat,
}

impl Pairing {
    /// `produced = returned`.
    pub fn holds(&self) -> bool {
        self.produced == self.returned
    }
}

/// [definition] **What a section's return yields**: the words' returns joined on the refinement's
/// clock ([`join`]), each word's covector on its opening change, and the adjoint pairing.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SectionReturn {
    pub joined: WordReturn,
    pub openings: Vec<ChangeCovector>,
    pub pairing: Pairing,
}

/// **The words' returns joined on the refinement's clock**: every element, transit and resonator
/// tick re-indexed by its word's open (`n·w`), the conductance covectors summed, the opening
/// covectors summed (each word's injection is the same moment, so its covector on `E` is their
/// sum), the stations' reads beside their covectors, and the released remainders joined.
pub fn join(
    returns: &[(WordReturn, ChangeCovector)],
    span: usize,
    reads: Vec<(Vec<Rat>, Vec<Rat>)>,
) -> Result<WordReturn, HnnError> {
    let Some((first, _)) = returns.first() else {
        return Err(HnnError::Shape {
            what: "a refinement's returns",
            expected: 1,
            found: 0,
        });
    };
    let mut joined = WordReturn {
        opening: first
            .opening
            .iter()
            .map(|wave| vec![Rat::zero(); wave.len()])
            .collect(),
        elements: vec![Vec::new(); first.elements.len()],
        transits: vec![Vec::new(); first.transits.len()],
        resonators: vec![Vec::new(); first.resonators.len()],
        conductance: vec![Rat::zero(); first.conductance.len()],
        reads,
        released: Remainders::default(),
    };
    for (n, (back, _)) in returns.iter().enumerate() {
        let offset = n * span;
        for (total, wave) in joined.opening.iter_mut().zip(&back.opening) {
            *total = add(total, wave);
        }
        for (total, ticks) in joined.elements.iter_mut().zip(&back.elements) {
            total.extend(ticks.iter().cloned().map(|mut tick| {
                tick.tick += offset;
                tick
            }));
        }
        for (total, ticks) in joined.transits.iter_mut().zip(&back.transits) {
            total.extend(ticks.iter().cloned().map(|mut tick| {
                tick.tick += offset;
                tick
            }));
        }
        for (total, ticks) in joined.resonators.iter_mut().zip(&back.resonators) {
            total.extend(ticks.iter().cloned().map(|mut tick| {
                tick.tick += offset;
                tick
            }));
        }
        for (total, term) in joined.conductance.iter_mut().zip(&back.conductance) {
            *total += term;
        }
        joined.released = joined.released.join(&back.released);
    }
    Ok(joined)
}

// -------------------------------------------------------------------------------------------
// learning

/// [definition] **The internal checks of one refinement** (module header): the balance closing,
/// the adjoint pairing (when checked), the section's release width, and the loci outside the
/// refinement's diamond (their count, and whether every one is unchanged by the deposit that
/// followed).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Checks {
    pub balance: RefinementBalance,
    pub pairing: Option<Pairing>,
    pub width: Rat,
    pub unreached: Option<(usize, bool)>,
}

/// [definition] **One refinement staged for its deposit**: the section's ratio against its
/// targets, its release, the composed return, the end change and the balance (the commit's
/// operands), and the pairing when checked.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Staged {
    pub ratio: HolonRatio,
    pub release: SectionRelease,
    pub composed: ComposedReturn,
    pub end: EndChange,
    pub balance: RefinementBalance,
    pub pairing: Option<Pairing>,
    pub released: Remainders,
    pub peak_bits: u64,
}

/// **Refine, compare and return one section** at the constitution's commit (module header,
/// "Learning"): the targets at the `locked` stations placed as the section's data ([`mask`] draws
/// the partition; none locked is the pinned September 29 path), the section refined at the cut with
/// the passage (the request continued by the locked data, one population, [`Refinement::passage`]),
/// released, compared at its unlocked stations only, its covector pulled back through the `K` words
/// and composed onto every locus inside the refinement's diamond, the passage entering through
/// `E_g`. With `check`, the refinement is also run on the executed charts with no transient split
/// and its return's pairing read ([`Pairing`]).
#[allow(clippy::too_many_arguments)]
pub fn stage(
    field: &Field,
    constitution: &Constitution,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    targets: &[usize],
    locked: &[bool],
    charts: &mut Charts,
    check: bool,
) -> Result<Staged, HnnError> {
    if targets.len() != declared.stations || locked.len() != declared.stations {
        return Err(HnnError::Shape {
            what: "one target and one lock per station",
            expected: declared.stations,
            found: targets.len().min(locked.len()),
        });
    }
    let cells: Vec<Option<usize>> = targets
        .iter()
        .zip(locked)
        .map(|(&target, &lock)| lock.then_some(target))
        .collect();
    // Nothing locked places nothing (the pinned September 29 path, on any receiving ring).
    let passage = declared.passage(field, current, moment, &cells)?;
    let compared: Vec<bool> = locked.iter().map(|lock| !lock).collect();
    let operands = Operands::at_cut_charted(field, constitution, current, charts)?;
    let injection = passage.open_storage(field, constitution, current)?;
    let pairing = if check {
        let unsplit = operands.clone().unsplit()?;
        let section =
            Section::refine_on(field, constitution, unsplit, injection.clone(), declared)?;
        let covector = section.compare_partition(targets, &compared)?.covector()?;
        Some(section.pull_back(&covector)?.pairing)
    } else {
        None
    };
    let section = Section::refine_on(field, constitution, operands, injection, declared)?;
    let release = section.release()?;
    let ratio = section.compare_partition(targets, &compared)?;
    let covector = ratio.covector()?;
    let end = section.end().clone();
    let balance = section.balance().clone();
    let released = section.released()?;
    let peak_bits = section.peak_bits();
    let back = section.pull_back(&covector)?;
    let composed = compose_return(
        field,
        constitution,
        &declared.diamond(field),
        current.lift(),
        current,
        &passage,
        &back.joined,
    )?;
    Ok(Staged {
        ratio,
        release,
        composed,
        end,
        balance,
        pairing,
        released: released.join(&back.joined.released),
        peak_bits,
    })
}

/// [definition; agent-inferred, September 29] **The comparison's code at a constitution** (the
/// lock's exact comparison, `hnn::constitution`, "At a node: the lock's half-turn"): the forward
/// half of [`stage`], its section refined at the cut with the passage (the request continued by the
/// locked targets), compared at its unlocked stations, and read as its code's enclosure. Nothing is
/// returned or deposited.
#[allow(clippy::too_many_arguments)]
pub fn comparison_code(
    field: &Field,
    constitution: &impl ConstitutionRead,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    targets: &[usize],
    locked: &[bool],
    charts: &mut Charts,
) -> Result<ExactInterval, HnnError> {
    if targets.len() != declared.stations || locked.len() != declared.stations {
        return Err(HnnError::Shape {
            what: "one target and one lock per station",
            expected: declared.stations,
            found: targets.len().min(locked.len()),
        });
    }
    let cells: Vec<Option<usize>> = targets
        .iter()
        .zip(locked)
        .map(|(&target, &lock)| lock.then_some(target))
        .collect();
    let passage = declared.passage(field, current, moment, &cells)?;
    let compared: Vec<bool> = locked.iter().map(|lock| !lock).collect();
    let section = Section::refine(field, constitution, current, &passage, declared, charts)?;
    section.compare_partition(targets, &compared)?.code_length()
}

/// [definition] **A generated section** ([`generate`]): its release (every station locked, at width
/// zero, or held with the stations that were plural when no unlocked station led), the refinements
/// it took, how many of their balances closed, and the stations each refinement locked, in order.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Generation {
    pub release: SectionRelease,
    pub refinements: usize,
    pub balances_closed: usize,
    pub locks: Vec<Vec<usize>>,
}

/// **Generate a section** (module header, "Relative phases between placed data"): the request's
/// placement fixed, nothing locked; each refinement reads every station jointly from the one refined
/// field with the locked data placed, and locks every unlocked station whose gap at the grain is the
/// largest (ties together). It stops when every station is locked, released at width zero (each lock
/// read a unique top cell), or when the largest gap is zero, held with the unlocked stations plural.
/// At most `m` refinements; the operands are read once at the cut.
pub fn generate(
    field: &Field,
    constitution: &impl ConstitutionRead,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    charts: &mut Charts,
) -> Result<Generation, HnnError> {
    if !field.is_source(declared.ring) {
        return Err(HnnError::MissingSourcePort {
            ring: declared.ring,
        });
    }
    let operands = Operands::at_cut_charted(field, constitution, current, charts)?;
    let stations = declared.stations;
    let mut locked: Vec<Option<usize>> = vec![None; stations];
    let mut tops: Vec<usize> = vec![declared.termination; stations];
    let mut locks: Vec<Vec<usize>> = Vec::new();
    let mut plural: Vec<usize> = Vec::new();
    let (mut refinements, mut balances_closed) = (0usize, 0usize);
    while locked.iter().any(Option::is_none) {
        let passage = declared.passage(field, current, moment, &locked)?;
        let injection = passage.open_storage(field, constitution, current)?;
        let section = Section::refine_on(field, constitution, operands.clone(), injection, declared)?;
        refinements += 1;
        balances_closed += usize::from(section.balance().closes());
        let readings: Vec<(usize, usize, BigInt)> = (0..stations)
            .filter(|&j| locked[j].is_none())
            .map(|j| {
                let (top, gap) = lock_reading(&section.faces().faces[j], declared.grain);
                (j, top, gap)
            })
            .collect();
        for &(j, top, _) in &readings {
            tops[j] = top;
        }
        let largest = readings
            .iter()
            .map(|(_, _, gap)| gap.clone())
            .max()
            .unwrap_or_else(BigInt::zero);
        if largest.is_zero() {
            plural = readings.iter().map(|&(j, ..)| j).collect();
            break;
        }
        let now: Vec<usize> = readings
            .iter()
            .filter(|(_, _, gap)| *gap == largest)
            .map(|&(j, top, _)| {
                locked[j] = Some(top);
                j
            })
            .collect();
        locks.push(now);
    }
    let classes: Vec<usize> = locked
        .iter()
        .zip(&tops)
        .map(|(lock, &top)| lock.unwrap_or(top))
        .collect();
    Ok(Generation {
        release: section_release(declared, classes, plural)?,
        refinements,
        balances_closed,
        locks,
    })
}

/// [definition; agent-inferred, September 29] **A section generated by the receiving bank**
/// ([`generate_by_bank`]): its release, the refinements it took, the stations each locked, the turn
/// readings made, and at every lock the bank's certificate (the members certified at the locked
/// reading's growth, and the executed turn's ticks whose balance closed, of those run), with each
/// lock's station, class, growth and runner-up growth; and the lock whose Floquet certificate was
/// refused, if one was, where the release stopped and held (September 30: a refused certificate is
/// a commit guard, never a tally).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BankGeneration {
    pub release: SectionRelease,
    pub refinements: usize,
    pub locks: Vec<Vec<usize>>,
    pub readings: usize,
    pub certified: usize,
    pub members: usize,
    pub ticks_closed: usize,
    pub ticks: usize,
    pub decisions: Vec<(usize, usize, Growth, Growth)>,
    pub uncertified: Option<(usize, usize)>,
}

/// [definition; agent-inferred, September 30] **One refinement of the bank's lock iteration**
/// ([`bank_release`]): the section placed before it, every open candidate `(station, class)` in
/// station-major order with its reading, each open station's top class, the eligible stations
/// (the top's flip and lock both certified) with their gaps, and the stations it locked.
#[derive(Clone, Debug)]
pub struct BankRefinement<R> {
    pub placed: Vec<Option<usize>>,
    pub open: Vec<(usize, usize)>,
    pub read: Vec<R>,
    pub tops: Vec<(usize, usize)>,
    pub eligible: Vec<(usize, usize, Rat)>,
    pub locked: Vec<usize>,
}

/// [definition; agent-inferred, September 30] **A candidate's reading as the lock iteration reads
/// it**: its joint growth enclosure.
pub trait JointGrowth {
    /// The turn's reading.
    fn reading(&self) -> &TurnReading;
    /// Its joint growth enclosure.
    fn joint(&self) -> &Growth {
        &self.reading().joint
    }
}

impl JointGrowth for TurnReading {
    fn reading(&self) -> &TurnReading {
        self
    }
}

impl JointGrowth for TurnCovector {
    fn reading(&self) -> &TurnReading {
        &self.reading
    }
}

/// [definition; agent-inferred, September 29] **Generate a section by the receiving bank's locks**
/// (module header, "The bank reads the superposed passage"). The request's placement is fixed and
/// nothing is locked. In each refinement, for every unlocked station and every class of the
/// exterior chart, the receiving ring's storage is the request's placement with the locked data
/// and that candidate placed at their stations' residues (`SourceMoment::continued`'s law over the
/// passage's one population, the other unlocked stations unplaced); the bank reads its turn
/// ([`ReceivingBank::read_turn`]). A station's reading is the lock's flip: its top candidate's joint
/// growth exceeds every other candidate's exactly ([`Growth::exceeds`], `θ = a/(a + K) > ½`) and the
/// bank locks there ([`Growth::is_locked`]); its gap is the top's `lower` less the largest other
/// `upper`. Every station of the largest positive gap locks (ties together), its reading certified
/// ([`ReceivingBank::certify_turn`]); a locked datum is placed for the next refinement. It stops when
/// every station is locked, released at width zero through `receiver::release` ([`Section::release`]'s
/// law), or when no unlocked station has a positive gap, held with them plural, or when a lock's
/// Floquet certificate is refused, held with the open stations plural (the refusal named). Nothing
/// is deposited: the constitution is read at its cut (`E`, placed through the source port), and the
/// bank's members are declared. The readings of one refinement are co-present regions: shared
/// immutable input, one output each, so they run on the host's cores.
#[allow(clippy::too_many_arguments)]
pub fn generate_by_bank(
    field: &Field,
    constitution: &impl ConstitutionRead,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    bank: &ReceivingBank,
    grain: u32,
) -> Result<BankGeneration, HnnError> {
    let ring = declared.ring;
    if !field.is_source(ring) {
        return Err(HnnError::MissingSourcePort { ring });
    }
    let placement = BankPlacement::of(field, constitution, current, moment, declared)?;
    let (generation, _) = bank_release(
        &placement,
        declared,
        field.alphabet(),
        bank,
        grain,
        |amplitudes| bank.read_turn(amplitudes, grain),
        false,
    )?;
    Ok(generation)
}

/// [definition; agent-inferred, September 30] **The bank's lock iteration, its one owner**
/// ([`generate_by_bank`]'s law, read by the release's own comparison `hnn::executed` with each
/// candidate's covector): every refinement reads every open candidate by `read`, decides each
/// open station's lock's flip and gap, locks the stations of the largest positive gap together,
/// certifies each lock's reading, and stops at the whole section, at a plural refinement, or at a
/// refused certificate. With `keep`, each refinement's readings are returned.
pub fn bank_release<R: JointGrowth + Send + Sync>(
    placement: &BankPlacement,
    declared: &Refinement,
    alphabet: usize,
    bank: &ReceivingBank,
    grain: u32,
    read: impl Fn(&[GaussianRat]) -> Result<R, HnnError> + Sync,
    keep: bool,
) -> Result<(BankGeneration, Vec<BankRefinement<R>>), HnnError> {
    use rayon::prelude::*;
    let stations = declared.stations;
    let mut locked: Vec<Option<usize>> = vec![None; stations];
    let mut tops: Vec<usize> = vec![declared.termination; stations];
    let mut locks: Vec<Vec<usize>> = Vec::new();
    let mut plural: Vec<usize> = Vec::new();
    let mut decisions = Vec::new();
    let mut kept = Vec::new();
    let mut uncertified = None;
    let (mut refinements, mut readings, mut certified, mut members) = (0, 0, 0, 0);
    let (mut ticks_closed, mut ticks) = (0, 0);
    while locked.iter().any(Option::is_none) {
        let placed = locked.clone();
        let storage = |station: usize, class: usize| -> Vec<Rat> {
            let mut cells = placed.clone();
            cells[station] = Some(class);
            placement.storage(&cells)
        };
        let open: Vec<(usize, usize)> = (0..stations)
            .filter(|&station| locked[station].is_none())
            .flat_map(|station| (0..alphabet).map(move |class| (station, class)))
            .collect();
        let read: Vec<R> = open
            .par_iter()
            .map(|&(station, class)| read(&turn(&storage(station, class))))
            .collect::<Result<Vec<_>, HnnError>>()?;
        refinements += 1;
        readings += read.len();
        // Each unlocked station's lock's flip: its top candidate and gap.
        let mut gaps: Vec<(usize, usize, Rat)> = Vec::new();
        let mut station_tops = Vec::new();
        for (index, chunk) in read.chunks(alphabet).enumerate() {
            let station = open[index * alphabet].0;
            let best = (0..alphabet)
                .max_by(|&a, &b| {
                    chunk[a]
                        .joint()
                        .lower
                        .cmp(&chunk[b].joint().lower)
                        .then(b.cmp(&a))
                })
                .expect("a class");
            tops[station] = best;
            station_tops.push((station, best));
            let top = chunk[best].joint();
            let runner = (0..alphabet)
                .filter(|&class| class != best)
                .map(|class| chunk[class].joint().upper.clone())
                .max();
            let flips = (0..alphabet)
                .filter(|&class| class != best)
                .all(|class| top.exceeds(chunk[class].joint()));
            if flips && top.is_locked() {
                let gap = match &runner {
                    Some(runner) => &top.lower - runner,
                    None => top.lower.clone(),
                };
                gaps.push((station, best, gap));
            }
        }
        let largest = gaps.iter().map(|(_, _, gap)| gap.clone()).max();
        let now: Vec<usize> = match &largest {
            Some(largest) => gaps
                .iter()
                .filter(|(_, _, gap)| gap == largest)
                .map(|&(station, _, _)| station)
                .collect(),
            None => Vec::new(),
        };
        let mut taken = Vec::new();
        for &station in &now {
            let class = tops[station];
            let index = open
                .iter()
                .position(|&pair| pair == (station, class))
                .expect("a read candidate");
            let reading = read[index].joint().clone();
            let amplitudes = turn(&storage(station, class));
            match bank.certify_turn(&amplitudes, read[index].reading(), grain) {
                Ok(certificate) => {
                    certified += certificate.certificates.len();
                    ticks_closed += certificate.closed;
                    ticks += certificate.ticks;
                }
                // A refused certificate refuses the lock and the release (a commit guard): with
                // the reading's upper end strictly outside every multiplier, the exact Stein solve
                // of the exact monodromy always certifies, so a refusal can only mean the reading
                // itself is wrong.
                Err(HnnError::UncertifiedFloquet { .. }) => {
                    uncertified = Some((station, class));
                    break;
                }
                Err(error) => return Err(error),
            }
            members += bank.pumps().len();
            let runner = (0..alphabet)
                .filter(|&other| other != class)
                .map(|other| read[index - class + other].joint().clone())
                .max_by(|a, b| a.upper.cmp(&b.upper))
                .expect("a runner-up");
            decisions.push((station, class, reading, runner));
            locked[station] = Some(class);
            taken.push(station);
        }
        let stop = now.is_empty() || uncertified.is_some();
        if stop {
            plural = (0..stations)
                .filter(|&station| locked[station].is_none())
                .collect();
            if let Some((station, _)) = uncertified {
                plural.retain(|&s| s != station);
                plural.insert(0, station);
            }
        }
        if keep {
            kept.push(BankRefinement {
                placed: placed.clone(),
                open,
                read,
                tops: station_tops,
                eligible: gaps,
                locked: taken.clone(),
            });
        }
        if !taken.is_empty() {
            locks.push(taken);
        }
        if stop {
            break;
        }
    }
    let classes: Vec<usize> = locked
        .iter()
        .zip(&tops)
        .map(|(lock, &top)| lock.unwrap_or(top))
        .collect();
    Ok((
        BankGeneration {
            release: section_release(declared, classes, plural)?,
            refinements,
            locks,
            readings,
            certified,
            members,
            ticks_closed,
            ticks,
            decisions,
            uncertified,
        },
        kept,
    ))
}

/// [definition; agent-inferred, September 29; the passage law, September 30] **The receiving ring's
/// storage under the passage** ([`generate_by_bank`]; module header, "The section continues the
/// request's passage"): each occupied phase's read of the request's raw counts
/// `P^(λ−c) E M[c]` on the receiving ring, the pair ports' normalized read, and, per station `j` and
/// class `x`, the datum's image `P^(λ − c_j) E e_x`, `c_j = τ + 1 + j` (mod `d`). A section's cells
/// `S` continue the request's passage, each datum at its transported weight over the span:
///
/// ```text
/// z(S) = z_pairs + Σ_c w_S(c) P^(λ−c) E M[c] + Σ_(j∈S) w_S(j) P^(λ − c_j) E e_(x_j)
/// w_S(k) = chart(ρ^(a_k) / (Σ_c n(c) ρ^(a_c) + Σ_(j∈S) ρ^(a_j)))
/// ```
///
/// with `a` each datum's age at the section's last station (`m + (τ − c mod d)` for a request
/// phase, `m − 1 − j` for station `j`) and `ρ` the navigator's transport modulus: at `ρ = 1` every
/// datum weighs `ν̂(n + |S|)`. The law of [`SourceMoment::continued`] then `open_storage`, read
/// without re-encoding the request for every candidate; held to it exactly by the owner's tests.
/// With nothing placed it is the request's own open.
#[derive(Clone, Debug)]
pub struct BankPlacement {
    reads: Vec<(u64, u64, Vec<Rat>)>,
    pairs: Vec<Rat>,
    images: Vec<Vec<Vec<Rat>>>,
    chart: PopulationChart,
    modulus: Rat,
    stations: u64,
    /// `ρ^a` for every age `a < d + m`.
    powers: Vec<Rat>,
    population: u64,
}

impl BankPlacement {
    /// The request's reads and every station's class images on the receiving ring. Refused, at a
    /// transport below modulus one, when the request and its declared stations span more than one
    /// turn ([`HnnError::AliasedAges`]).
    pub fn of(
        field: &Field,
        constitution: &impl ConstitutionRead,
        current: &Current,
        moment: &SourceMoment,
        declared: &Refinement,
    ) -> Result<Self, HnnError> {
        let ring = declared.ring;
        let port = constitution
            .source_port(ring)
            .ok_or(HnnError::MissingSourcePort { ring })?;
        let geometry = field.ring(ring);
        let period = geometry.period();
        let modulus = constitution.transport(ring);
        let stations = declared.stations as u64;
        // The span's check: the moment read over its declared stations (every station placed).
        let full = moment.continued(field, current, ring, &vec![Some(0); declared.stations])?;
        full.phase_weights(field, ring, &modulus)?;
        let (raw, pairs) = moment.open_parts(field, constitution, current, ring)?;
        let phase = current.phase(field, ring)?;
        let reads = raw
            .into_iter()
            .map(|(c, read)| -> Result<(u64, u64, Vec<Rat>), HnnError> {
                let c = c as u64;
                let age = stations + (phase + period - c) % period;
                let count: u64 = moment.phase_counts(ring, c as usize)?.iter().sum();
                Ok((age, count, read))
            })
            .collect::<Result<Vec<_>, _>>()?;
        let lift = current.lift()[ring].clone();
        let columns: Vec<Vec<Rat>> = (0..field.alphabet())
            .map(|class| {
                (0..port.rows())
                    .map(|row| port.get(row, class).cloned())
                    .collect::<Result<Vec<_>, _>>()
            })
            .collect::<Result<Vec<_>, _>>()?;
        let images = (0..declared.stations)
            .map(|station| {
                let residue = (phase + 1 + station as u64) % period;
                let rotation = &lift - BigInt::from(residue);
                columns
                    .iter()
                    .map(|column| geometry.rotate(column, &rotation))
                    .collect()
            })
            .collect();
        let mut powers = Vec::with_capacity((period + stations) as usize);
        let mut power = Rat::one();
        for _ in 0..period + stations {
            powers.push(power.clone());
            power *= &modulus;
        }
        Ok(Self {
            reads,
            pairs,
            images,
            chart: PopulationChart::of(field),
            modulus,
            stations,
            powers,
            population: moment.population(ring)?,
        })
    }

    /// The navigator's transport modulus the placement weighs at.
    pub fn modulus(&self) -> &Rat {
        &self.modulus
    }

    /// Station `j`'s age at the section's last station.
    fn station_age(&self, station: usize) -> u64 {
        self.stations - 1 - station as u64
    }

    /// The span's transported mass `Σ_c n(c) ρ^(a_c) + Σ_(j∈S) ρ^(a_j)`, exactly.
    fn mass(&self, cells: &[Option<usize>]) -> Rat {
        let mut mass = Rat::zero();
        for (age, count, _) in &self.reads {
            mass += &self.powers[*age as usize] * Rat::from_integer(BigInt::from(*count));
        }
        for (station, cell) in cells.iter().enumerate() {
            if cell.is_some() {
                mass += &self.powers[self.station_age(station) as usize];
            }
        }
        mass
    }

    /// **The passage's weights** with the section's cells placed: each request phase's and each
    /// placed station's `w_S`, on the population chart; at `ρ = 1` all `ν̂(n + |S|)`.
    #[allow(clippy::type_complexity)]
    pub fn weights(&self, cells: &[Option<usize>]) -> (Vec<Rat>, Vec<Option<Rat>>) {
        if self.modulus.is_one() {
            let placed = cells.iter().filter(|cell| cell.is_some()).count() as u64;
            let nu = self.chart.value(self.population + placed);
            return (
                vec![nu.clone(); self.reads.len()],
                cells.iter().map(|cell| cell.map(|_| nu.clone())).collect(),
            );
        }
        let mass = self.mass(cells);
        let weigh = |age: u64| self.chart.chart(&(&self.powers[age as usize] / &mass));
        (
            self.reads.iter().map(|(age, _, _)| weigh(*age)).collect(),
            cells
                .iter()
                .enumerate()
                .map(|(station, cell)| cell.map(|_| weigh(self.station_age(station))))
                .collect(),
        )
    }

    /// **The receiving ring's storage** with the section's cells placed (a station's class, or
    /// unplaced): the pair ports' read plus every datum of the passage at its transported weight.
    pub fn storage(&self, cells: &[Option<usize>]) -> Vec<Rat> {
        let (request, section) = self.weights(cells);
        let mut storage = self.pairs.clone();
        for ((_, _, read), weight) in self.reads.iter().zip(&request) {
            for (value, add) in storage.iter_mut().zip(read) {
                *value += add * weight;
            }
        }
        for (station, (cell, weight)) in cells.iter().zip(&section).enumerate() {
            if let (Some(class), Some(weight)) = (cell, weight) {
                for (value, add) in storage.iter_mut().zip(&self.images[station][*class]) {
                    *value += add * weight;
                }
            }
        }
        storage
    }

    /// The storage at the exact transported weights at a modulus (no chart): the test's reference
    /// for [`BankPlacement::modulus_derivative`].
    #[cfg(test)]
    pub(crate) fn exact_storage(&self, cells: &[Option<usize>], modulus: &Rat) -> Vec<Rat> {
        let power = |age: u64| crate::hnn::moment::modulus_power(modulus, age);
        let mut data: Vec<(u64, Rat, &Vec<Rat>)> = self
            .reads
            .iter()
            .map(|(age, count, read)| (*age, Rat::from_integer(BigInt::from(*count)), read))
            .collect();
        for (station, cell) in cells.iter().enumerate() {
            if let Some(class) = cell {
                data.push((self.station_age(station), Rat::one(), &self.images[station][*class]));
            }
        }
        let mass: Rat = data.iter().map(|(age, count, _)| power(*age) * count).sum();
        let mut storage = self.pairs.clone();
        for (age, _, read) in data {
            let weight = power(age) / &mass;
            for (value, add) in storage.iter_mut().zip(read) {
                *value += add * &weight;
            }
        }
        storage
    }

    /// [definition; agent-inferred, September 30] **The storage's derivative in the transport
    /// modulus** at the exact weights `w_k = ρ^(a_k)/mass`: `∂w_k/∂ρ = w_k (a_k − ā)/ρ`, `ā` the
    /// span's weighted mean age, so `∂z/∂ρ = Σ_k ∂w_k/∂ρ · (datum k's read)`; the modulus's
    /// covector pairs with it (`hnn::executed`, "The committed move").
    pub fn modulus_derivative(&self, cells: &[Option<usize>]) -> Vec<Rat> {
        let mass = self.mass(cells);
        let mut data: Vec<(u64, Rat, &Vec<Rat>)> = self
            .reads
            .iter()
            .map(|(age, count, read)| (*age, Rat::from_integer(BigInt::from(*count)), read))
            .collect();
        for (station, cell) in cells.iter().enumerate() {
            if let Some(class) = cell {
                data.push((self.station_age(station), Rat::one(), &self.images[station][*class]));
            }
        }
        let mean: Rat = data
            .iter()
            .map(|(age, count, _)| {
                &self.powers[*age as usize] * count * Rat::from_integer(BigInt::from(*age))
            })
            .sum::<Rat>()
            / &mass;
        let mut derivative = vec![Rat::zero(); self.pairs.len()];
        for (age, _, read) in data {
            let weight = &self.powers[age as usize] / &mass;
            let slope = weight * (Rat::from_integer(BigInt::from(age)) - &mean) / &self.modulus;
            if slope.is_zero() {
                continue;
            }
            for (value, add) in derivative.iter_mut().zip(read) {
                *value += add * &slope;
            }
        }
        derivative
    }
}

// -------------------------------------------------------------------------------------------
// the bank's learning path

/// [definition; agent-inferred, September 29] **The bank's images at a constitution** (module
/// header, "The bank's learning path"): every class's column of the source port `E` placed at every
/// rotation `r` of the receiving ring, read by the bank's resonance chart, `Φ(P^r E e_x)`; and each
/// rotation's node images (`hnn::field::Ring::rotate`). Every storage the bank reads in training is a
/// sum of these images over its placements (held to [`BankPlacement::storage`] exactly by the
/// owner's test), so a request's readings are sums, not new turns. Read once per constitution; the
/// images are co-present regions (shared `E`, one output each).
#[derive(Clone, Debug)]
pub struct BankImages {
    chart: BankChart,
    ring: usize,
    classes: usize,
    images: Vec<Vec<Resonance>>,
    rotations: Vec<Vec<usize>>,
}

impl BankImages {
    /// The images of `E` at the constitution's cut on the refinement's receiving ring. Refused
    /// unless the ring is a source ring and the field declares no pair offset (the bank's comparison
    /// reads the first-order moment through `E` alone).
    pub fn of(
        field: &Field,
        constitution: &impl ConstitutionRead,
        declared: &Refinement,
        bank: &ReceivingBank,
    ) -> Result<Self, HnnError> {
        use rayon::prelude::*;
        let ring = declared.ring;
        if !field.offsets().is_empty() {
            return Err(HnnError::Shape {
                what: "the bank's comparison on a field with no pair offset",
                expected: 0,
                found: field.offsets().len(),
            });
        }
        // The face's shared resonance is one per request only at a transport of modulus one: below
        // it, each candidate's station sets the span's mass (module header, "The section continues
        // the request's passage"). The face's dissipative form is owed.
        let modulus = constitution.transport(ring);
        if !modulus.is_one() {
            return Err(HnnError::FaceTransport { ring, modulus });
        }
        let port = constitution
            .source_port(ring)
            .ok_or(HnnError::MissingSourcePort { ring })?;
        let geometry = field.ring(ring);
        let period = geometry.period() as usize;
        let chart = bank.chart(period)?;
        let classes = field.alphabet();
        let columns: Vec<Vec<Rat>> = (0..classes)
            .map(|class| {
                (0..port.rows())
                    .map(|row| port.get(row, class).cloned())
                    .collect::<Result<Vec<_>, _>>()
            })
            .collect::<Result<Vec<_>, _>>()?;
        let pairs: Vec<(usize, usize)> = (0..period)
            .flat_map(|r| (0..classes).map(move |x| (r, x)))
            .collect();
        let read: Vec<Resonance> = pairs
            .par_iter()
            .map(|&(r, x)| chart.of_storage(&geometry.rotate(&columns[x], &BigInt::from(r))))
            .collect::<Result<Vec<_>, HnnError>>()?;
        let images = read.chunks(classes).map(<[Resonance]>::to_vec).collect();
        let indices: Vec<Rat> = (0..geometry.width())
            .map(|i| Rat::from_integer(BigInt::from(i / 2)))
            .collect();
        let rotations = (0..period)
            .map(|r| {
                let rotated = geometry.rotate(&indices, &BigInt::from(r));
                let mut images = vec![0usize; period];
                for target in 0..period {
                    let node = rotated[2 * target]
                        .to_integer()
                        .to_usize()
                        .expect("a rotation permutes the nodes");
                    images[node] = target;
                }
                images
            })
            .collect();
        Ok(Self {
            chart,
            ring,
            classes,
            images,
            rotations,
        })
    }

    /// The bank's resonance chart over the ring's turn.
    pub fn chart(&self) -> &BankChart {
        &self.chart
    }

    /// `Φ(P^r E e_x)`.
    pub fn image(&self, rotation: usize, class: usize) -> &Resonance {
        &self.images[rotation][class]
    }

    /// The rotation `r ∈ [0, d)` of a lift difference.
    fn rotation(&self, shift: &BigInt) -> usize {
        let period = BigInt::from(self.rotations.len());
        ((shift % &period + &period) % &period)
            .to_usize()
            .expect("a rotation lies below the period")
    }

    /// `(P^r)ᵀ v = P^(−r) v`, on the node images: a storage covector carried back through a
    /// placement's rotation.
    fn rotate_back(&self, vector: &[Rat], rotation: usize) -> Vec<Rat> {
        let mut back = vec![Rat::zero(); vector.len()];
        for (node, &target) in self.rotations[rotation].iter().enumerate() {
            back[2 * node] = vector[2 * target].clone();
            back[2 * node + 1] = vector[2 * target + 1].clone();
        }
        back
    }
}

/// [definition; agent-inferred, September 29] **One request's bank comparison, staged**
/// ([`stage_bank`]; module header, "The bank's learning path"): each compared station's reading
/// (its target, the face's mass at the target `θ_t` exact, the face's top class, `A₀` and `a₀`);
/// the request's shared placements (each phase's rotation and feature) with the score's gradient
/// coefficients on their shared resonance; each compared station's rotation and every candidate's
/// gradient coefficients; the passage's weight `ν̂(n + v + 1)`; the gradient on each member's
/// `p_m²`; the comparisons skipped (a target the bank reads with no power has no finite code); and
/// the code `Σ −log₂ θ_t`, enclosed.
#[derive(Clone, Debug)]
pub struct BankStaged {
    pub stations: Vec<BankStationReading>,
    common: Vec<(usize, Vec<Rat>)>,
    shared: Vec<[GaussianRat; 2]>,
    candidates: Vec<(usize, Vec<Vec<[GaussianRat; 2]>>)>,
    weight: Rat,
    pub pumps: Vec<Rat>,
    pub skipped: usize,
    pub code: ExactInterval,
}

/// [definition] **One compared station's bank reading** ([`BankStaged`]): its station and target,
/// the face's exact mass at the target, the face's top class, `A₀` and `a₀`, and the bound on its
/// covector's rounding to the dyadic face (at its ceiling).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct BankStationReading {
    pub station: usize,
    pub target: usize,
    pub mass: Rat,
    pub top: usize,
    pub total: Rat,
    pub reading: Rat,
    pub rounding: Rat,
}

/// [definition; agent-inferred] **The bank covector's dyadic face**: each reading's covector at 64
/// significant bits (the certificate's face), so the returns' denominators are the readings' own
/// powers of 2 and 5 and not every station's normalizer; the rounding is charged exactly
/// (`hnn::constitution::BankReach::curvature`), and its bound is read at 16 significant bits.
const COVECTOR_BITS: u32 = 64;
const ROUNDING_BITS: u32 = 16;

/// [definition; agent-inferred, September 29] **Stage one request's bank comparison** (module
/// header, "The bank's learning path"; Lean `HNN/BankFace`). The partition is the readout's
/// ([`mask`]): the locked stations' targets placed, and at every compared station `j` every class
/// `x` placed there with them and the request over the passage's population `n + v + 1`
/// (generation's candidates, [`generate_by_bank`]). The bank reads each candidate's storage by its second-order face
/// `A(x) = Σ_m p_m² (|W⁺_m|² + |W⁻_m|²)`; the station's face is the lock's exchange face over the
/// candidates, `θ_x = A(x)/Σ_y A(y)`, compared with the target class: the loss
/// `ℓ = log(θ_t)⁻¹ = log Σ_y A(y) − log A(t)` (nats), its covector on each reading
/// `∂ℓ/∂A(x) = 1/Σ_y A(y) − [x = t]/A(t)` (on `log A(x)`: `θ_x − q_x`), carried to the resonances by
/// `d|W|² = 2 Re(conj W dW)` and to the storage through the chart (`BankChart::covector`), then to
/// `E` through each placement; `E` is read through the images ([`BankImages::of`], at the cut).
/// Nothing is deposited here.
pub fn stage_bank(
    field: &Field,
    current: &Current,
    moment: &SourceMoment,
    declared: &Refinement,
    images: &BankImages,
    targets: &[usize],
    locked: &[bool],
) -> Result<BankStaged, HnnError> {
    let ring = declared.ring;
    if images.ring != ring {
        return Err(HnnError::MissingSourcePort { ring });
    }
    if targets.len() != declared.stations || locked.len() != declared.stations {
        return Err(HnnError::Shape {
            what: "one target and one lock per station",
            expected: declared.stations,
            found: targets.len().min(locked.len()),
        });
    }
    let chart = images.chart();
    let period = chart.ticks();
    let lift = current.lift()[ring].clone();
    let phase = current.phase(field, ring)? as usize;
    let station_rotation = |station: usize| -> usize {
        images.rotation(&(&lift - BigInt::from((phase + 1 + station) % period)))
    };
    let placed = locked.iter().filter(|&&lock| lock).count() as u64;
    // The passage's one population (module header, "The section continues the request's
    // passage"): the request's cells, the locked stations and the candidate.
    let weight = PopulationChart::of(field).value(moment.population(ring)? + placed + 1);
    // The shared placements: the request's phases and the locked stations, by phase.
    let mut common: Vec<(usize, Vec<Rat>)> = Vec::new();
    for c in 0..period {
        let counts = moment.phase_counts(ring, c)?;
        let mut feature = if counts.iter().any(|&n| n != 0) {
            Some(
                counts
                    .iter()
                    .map(|&count| Rat::from_integer(BigInt::from(count)) * &weight)
                    .collect::<Vec<_>>(),
            )
        } else {
            None
        };
        for (station, &lock) in locked.iter().enumerate() {
            if lock && (phase + 1 + station) % period == c {
                let feature = feature.get_or_insert_with(|| vec![Rat::zero(); images.classes]);
                feature[targets[station]] += &weight;
            }
        }
        if let Some(feature) = feature {
            common.push((images.rotation(&(&lift - BigInt::from(c))), feature));
        }
    }
    let mut shared_resonance = Resonance::zero(chart.members());
    for (rotation, feature) in &common {
        for (class, count) in feature.iter().enumerate() {
            if !count.is_zero() {
                shared_resonance = shared_resonance.plus(images.image(*rotation, class), count);
            }
        }
    }
    let members = chart.members();
    let mut shared = vec![[GaussianRat::zero(), GaussianRat::zero()]; members];
    let mut candidates = Vec::new();
    let mut stations = Vec::new();
    let mut pumps = vec![Rat::zero(); members];
    let mut skipped = 0;
    let mut code = ExactInterval::point(Rat::zero());
    // Each compared station reads only the shared resonance and the images: the stations are
    // co-present regions, each returning its reading, joined below in station order.
    type StationRead = (
        usize,
        Vec<Vec<[GaussianRat; 2]>>,
        Vec<Rat>,
        ExactInterval,
        BankStationReading,
    );
    let compared: Vec<usize> = (0..declared.stations).filter(|&j| !locked[j]).collect();
    let read_station = |station: usize| -> Result<Option<StationRead>, HnnError> {
        let rotation = station_rotation(station);
        let read: Vec<Resonance> = (0..images.classes)
            .map(|class| shared_resonance.plus(images.image(rotation, class), &weight))
            .collect();
        let readings: Vec<Rat> = read.iter().map(|w| w.reading(chart)).collect();
        let total: Rat = readings.iter().sum();
        let target = targets[station];
        let at_target = readings[target].clone();
        if !at_target.is_positive() {
            return Ok(None);
        }
        let mass = &at_target / &total;
        let code = crate::ratio::algebraic::interval_difference(
            &ExactInterval::point(Rat::zero()),
            &crate::ratio::algebraic::log2_enclosure(&mass)?,
        )?;
        let top = (0..images.classes)
            .max_by(|&a, &b| readings[a].cmp(&readings[b]).then(b.cmp(&a)))
            .expect("a class");
        // The covector on each reading at its dyadic face (module header, "The bank's learning
        // path"): 64 significant bits toward zero, its exact rounding bounded per station and
        // charged by the certificate (`hnn::constitution::BankReach::curvature`).
        let mut rounding = Rat::zero();
        let mut pumps = vec![Rat::zero(); members];
        let coefficients: Vec<Vec<[GaussianRat; 2]>> = read
            .iter()
            .enumerate()
            .map(|(class, resonance)| {
                let mut exact = Rat::one() / &total;
                if class == target {
                    exact -= Rat::one() / &at_target;
                }
                let covector = if exact.is_negative() {
                    -significant(&-&exact, COVECTOR_BITS, false)
                } else {
                    significant(&exact, COVECTOR_BITS, false)
                };
                let error = (&exact - &covector).abs();
                if error > rounding {
                    rounding = error;
                }
                for (pump, power) in pumps.iter_mut().zip(resonance.powers()) {
                    *pump += &covector * power;
                }
                resonance.gradient(chart, &covector)
            })
            .collect();
        Ok(Some((
            rotation,
            coefficients,
            pumps,
            code,
            BankStationReading {
                station,
                target,
                mass,
                top,
                total,
                reading: at_target,
                rounding: significant(&rounding, ROUNDING_BITS, true),
            },
        )))
    };
    let read: Vec<Option<StationRead>> = {
        use rayon::prelude::*;
        compared
            .par_iter()
            .map(|&station| read_station(station))
            .collect::<Result<Vec<_>, HnnError>>()?
    };
    for station in read {
        let Some((rotation, coefficients, station_pumps, station_code, reading)) = station else {
            skipped += 1;
            continue;
        };
        code = crate::ratio::algebraic::interval_sum(&code, &station_code)?;
        for (pump, add) in pumps.iter_mut().zip(station_pumps) {
            *pump += add;
        }
        for per_class in &coefficients {
            for (sum, add) in shared.iter_mut().zip(per_class) {
                for side in 0..2 {
                    sum[side] = sum[side].add(&add[side]);
                }
            }
        }
        candidates.push((rotation, coefficients));
        stations.push(reading);
    }
    Ok(BankStaged {
        stations,
        common,
        shared,
        candidates,
        weight,
        pumps,
        skipped,
        code,
    })
}

/// [definition; agent-inferred, September 29] **The bank's reach over a batch** (module header, "The
/// bank's learning path"; `hnn::constitution::BankReach`): the bank's returns at the source port,
/// one per shared phase of each request (its feature the phase's counts over the passage's
/// population, its covector the
/// shared gradient carried back through the phase's rotation) and one per class over the batch (its
/// feature `e_x` at the weight `Σ ν²` over every candidate placement, its covector their
/// `ν`-weighted sum over that weight: the same unit step, alignment and metric as one return a
/// placement), each the descent covector; and the certificate's data.
pub fn bank_reach(images: &BankImages, staged: &[BankStaged]) -> BankReach {
    let chart = images.chart();
    let classes = images.classes;
    let negated = |v: Vec<Rat>| -> Vec<Rat> { v.into_iter().map(|x| -x).collect() };
    let mut samples = Vec::new();
    let mut requests = Vec::new();
    let period = images.rotations.len();
    let members = chart.members();
    // Λ[x][r]: the candidates' ν-weighted coefficients by class and rotation.
    let mut sums: Vec<Vec<Vec<[GaussianRat; 2]>>> =
        vec![vec![vec![[GaussianRat::zero(), GaussianRat::zero()]; members]; period]; classes];
    let mut weight = Rat::zero();
    for request in staged {
        if request.stations.is_empty() {
            continue;
        }
        let shared = chart.covector(&request.shared);
        for (rotation, feature) in &request.common {
            let back = images.rotate_back(&shared, *rotation);
            samples.push(Sample {
                weight: Rat::one(),
                feature: feature.clone(),
                covector: negated(back),
            });
        }
        for (rotation, coefficients) in &request.candidates {
            weight += &request.weight * &request.weight;
            for (class, per_class) in coefficients.iter().enumerate() {
                for (sum, add) in sums[class][*rotation].iter_mut().zip(per_class) {
                    for side in 0..2 {
                        sum[side] = sum[side].add(&add[side].scale(&request.weight));
                    }
                }
            }
        }
        requests.push(BankRequest {
            common: request
                .common
                .iter()
                .map(|(rotation, feature)| (images.rotations[*rotation].clone(), feature.clone()))
                .collect(),
            weight: request.weight.clone(),
            stations: request
                .stations
                .iter()
                .zip(&request.candidates)
                .map(|(reading, (rotation, _))| BankStation {
                    images: images.rotations[*rotation].clone(),
                    total: reading.total.clone(),
                    target: reading.reading.clone(),
                    class: reading.target,
                    rounding: reading.rounding.clone(),
                })
                .collect(),
        });
    }
    if weight.is_positive() {
        // Each class's return reads only its own sums: the classes are co-present regions.
        use rayon::prelude::*;
        let by_class: Vec<Option<Sample>> = sums
            .par_iter()
            .enumerate()
            .map(|(class, by_rotation)| {
                let mut covector: Option<Vec<Rat>> = None;
                for (rotation, coefficients) in by_rotation.iter().enumerate() {
                    if coefficients.iter().all(|pair| pair.iter().all(GaussianRat::is_zero)) {
                        continue;
                    }
                    let back = images.rotate_back(&chart.covector(coefficients), rotation);
                    covector = Some(match covector {
                        Some(sum) => add(&sum, &back),
                        None => back,
                    });
                }
                let covector = covector?;
                let mut feature = vec![Rat::zero(); classes];
                feature[class] = Rat::one();
                Some(Sample {
                    weight: weight.clone(),
                    feature,
                    covector: covector.iter().map(|x| -(x / &weight)).collect(),
                })
            })
            .collect();
        samples.extend(by_class.into_iter().flatten());
    }
    BankReach {
        ring: images.ring,
        samples,
        gain: chart.gain(),
        classes,
        requests,
    }
}

/// **The deposit of a batch with the receiving bank's comparison beside it** (module header, "The
/// bank's learning path"): [`deposit_of`] with the bank's reach, whose returns join the source
/// port's window and whose curvature the certified step reads.
pub fn deposit_with_bank(
    constitution: &Constitution,
    declared: &Refinement,
    composed: &[ComposedReturn],
    bank: BankReach,
) -> Result<Deposit, HnnError> {
    Ok(deposit_of(constitution, declared, composed)?.with_bank(bank))
}

/// **The deposit of a set of staged refinements at one commit** (module header): every linear
/// locus's samples gathered into one window (the normal law sums its samples' terms), every factor
/// family's descent directions and feature energies summed into one step (a shared operand's
/// gradient is the sum over its uses), the loci reached united, and the refinement's reach
/// ([`Refinement::reach`]) at the most phases one of its moments occupied. No landmark and no
/// receiving-face step is staged.
pub fn deposit_of(
    constitution: &Constitution,
    declared: &Refinement,
    composed: &[ComposedReturn],
) -> Result<Deposit, HnnError> {
    let mut linear: BTreeMap<LinearLocus, Vec<crate::hnn::constitution::Sample>> = BTreeMap::new();
    let mut order: Vec<LinearLocus> = Vec::new();
    let mut factors: Vec<FactorStep> = Vec::new();
    let mut reached: Vec<Locus> = Vec::new();
    for part in composed {
        for step in &part.linear {
            if !linear.contains_key(&step.locus) {
                order.push(step.locus);
            }
            linear
                .entry(step.locus)
                .or_default()
                .extend(step.samples.iter().cloned());
        }
        for step in &part.factors {
            match factors
                .iter_mut()
                .find(|kept| same_family(&kept.gradient, &step.gradient))
            {
                Some(kept) => {
                    kept.gradient = summed(&kept.gradient, &step.gradient)?;
                    kept.energy += &step.energy;
                    // One return's covector scale over the joined windows: the largest.
                    if step.covector > kept.covector {
                        kept.covector = step.covector.clone();
                    }
                }
                None => factors.push(step.clone()),
            }
        }
        for locus in &part.reached {
            if !reached.contains(locus) {
                reached.push(*locus);
            }
        }
    }
    let linear: Vec<LinearStep> = order
        .into_iter()
        .map(|locus| LinearStep {
            locus,
            samples: linear.remove(&locus).unwrap_or_default(),
        })
        .collect();
    let phases = composed.iter().map(|part| part.phases).max().unwrap_or(0);
    Ok(Deposit::new(constitution.commit(), linear, factors, reached)
        .with_reach(declared.reach(phases)))
}

/// Whether two factor steps descend the same family.
fn same_family(left: &FactorGradient, right: &FactorGradient) -> bool {
    use FactorGradient::*;
    match (left, right) {
        (Passive { ring: a, .. }, Passive { ring: b, .. })
        | (Slices { ring: a, .. }, Slices { ring: b, .. })
        | (Standing { ring: a, .. }, Standing { ring: b, .. }) => a == b,
        (
            Resonator {
                ring: a,
                family: f,
                ..
            },
            Resonator {
                ring: b,
                family: g,
                ..
            },
        ) => a == b && f == g,
        (
            PairPort {
                ring: a,
                offset: o,
                ..
            },
            PairPort {
                ring: b,
                offset: p,
                ..
            },
        ) => a == b && o == p,
        (Storage { contact: a, .. }, Storage { contact: b, .. })
        | (Stiffness { contact: a, .. }, Stiffness { contact: b, .. })
        | (Dissipation { contact: a, .. }, Dissipation { contact: b, .. }) => a == b,
        _ => false,
    }
}

/// The sum of two descent directions of the same family.
fn summed(left: &FactorGradient, right: &FactorGradient) -> Result<FactorGradient, HnnError> {
    use FactorGradient::*;
    let rows = |a: &[Vec<Rat>], b: &[Vec<Rat>]| -> Vec<Vec<Rat>> {
        a.iter().zip(b).map(|(x, y)| add(x, y)).collect()
    };
    Ok(match (left, right) {
        (Passive { ring, gradient: a }, Passive { gradient: b, .. }) => Passive {
            ring: *ring,
            gradient: a.add(b)?,
        },
        (Slices { ring, gradient: a }, Slices { gradient: b, .. }) => Slices {
            ring: *ring,
            gradient: a
                .iter()
                .zip(b)
                .map(|((u, v), (x, y))| (add(u, x), add(v, y)))
                .collect(),
        },
        (
            Standing {
                ring,
                gradient: a,
                reach: left,
            },
            Standing {
                gradient: b,
                reach: right,
                ..
            },
        ) => {
            // The chart's rings, each with the energies of both windows (one refinement's each).
            let mut reach = left.clone();
            for (r, energy) in right {
                match reach.iter_mut().find(|(kept, _)| kept == r) {
                    Some((_, kept)) => *kept += energy,
                    None => reach.push((*r, energy.clone())),
                }
            }
            Standing {
                ring: *ring,
                gradient: add(a, b),
                reach,
            }
        }
        (
            Resonator {
                ring,
                family,
                gradient: a,
            },
            Resonator { gradient: b, .. },
        ) => Resonator {
            ring: *ring,
            family: *family,
            gradient: a + b,
        },
        (
            PairPort {
                ring,
                offset,
                outputs: a,
                current: c,
                earlier: e,
            },
            PairPort {
                outputs: b,
                current: d,
                earlier: f,
                ..
            },
        ) => PairPort {
            ring: *ring,
            offset: *offset,
            outputs: rows(a, b),
            current: rows(c, d),
            earlier: rows(e, f),
        },
        (Storage { contact, gradient: a }, Storage { gradient: b, .. }) => Storage {
            contact: *contact,
            gradient: a.add(b)?,
        },
        (Stiffness { contact, gradient: a }, Stiffness { gradient: b, .. }) => Stiffness {
            contact: *contact,
            gradient: a.add(b)?,
        },
        (Dissipation { contact, gradient: a }, Dissipation { gradient: b, .. }) => Dissipation {
            contact: *contact,
            gradient: a.add(b)?,
        },
        _ => {
            return Err(HnnError::Shape {
                what: "two descent directions of one factor family",
                expected: 1,
                found: 2,
            });
        }
    })
}

/// **Every locus's learned material as the forward pass reads it**, flattened, with its deposit
/// clock: the check of the loci a deposit did not reach.
fn material(constitution: &Constitution, field: &Field, locus: Locus) -> (Vec<Rat>, u64) {
    let mut values: Vec<Rat> = Vec::new();
    match locus {
        Locus::Element(g) => {
            values.extend(constitution.passive_factor(g).entries().iter().cloned());
            values.extend(constitution.contrast_port(g).entries().iter().cloned());
            for (u, v) in constitution.slices(g) {
                values.extend(u.iter().cloned());
                values.extend(v.iter().cloned());
            }
        }
        Locus::Standing(g) => values.extend(constitution.standing(g).iter().cloned()),
        Locus::SourcePort(g) => {
            if let Some(port) = constitution.source_port(g) {
                values.extend(port.entries().iter().cloned());
            }
            for &offset in field.offsets() {
                if let Some(pair) = constitution.pair_port(g, offset) {
                    for family in [pair.outputs(), pair.current_reads(), pair.earlier_reads()] {
                        values.extend(family.iter().flatten().cloned());
                    }
                }
            }
        }
        Locus::ReceivingMap(g) => {
            if let Some(map) = constitution.receiving_map(g) {
                values.extend(map.entries().iter().cloned());
            }
        }
        Locus::Channel(a) => {
            for form in [
                constitution.contact_storage(a),
                constitution.contact_stiffness(a),
                constitution.contact_dissipation(a),
            ] {
                values.extend(form.entries().iter().cloned());
            }
        }
        Locus::Resonator(g) => {
            if let Some(resonator) = constitution.ring_resonator(g) {
                values.extend(resonator.gains().iter().cloned());
            }
        }
        Locus::Junction(_) | Locus::Conductance(_) => {}
    }
    (values, constitution.clock(locus))
}

/// **The loci a refinement's deposit did not reach are unchanged** (module header, the third check;
/// Lean `HNN/Retention.deposit_descends`): every locus outside the refinement's diamond has the same
/// learned material and deposit clock in the successor as in the predecessor. Returns the count of
/// such loci and whether every one is unchanged.
pub fn unreached_unchanged(
    field: &Field,
    before: &Constitution,
    after: &Constitution,
    diamond: &Diamond,
) -> (usize, bool) {
    let mut count = 0;
    let mut unchanged = true;
    for locus in loci(field) {
        if diamond.retains(field, locus) && !before.released().contains(&locus) {
            continue;
        }
        count += 1;
        unchanged &= material(before, field, locus) == material(after, field, locus);
    }
    (count, unchanged)
}
